from fractions import Fraction

SCALE = 10**50


def ceildiv(a, b):
    return -((-a)//b)


class I:
    __slots__ = ('lo', 'hi')

    def __init__(self, lo, hi=None):
        self.lo = int(lo)
        self.hi = int(lo if hi is None else hi)
        assert self.lo <= self.hi

    @staticmethod
    def rational(n, d=1):
        return I(n*SCALE//d, ceildiv(n*SCALE, d))

    def __add__(a, b):
        return I(a.lo+b.lo, a.hi+b.hi)

    def __neg__(a):
        return I(-a.hi, -a.lo)

    def __sub__(a, b):
        return a+(-b)

    def __mul__(a, b):
        v = [a.lo*b.lo, a.lo*b.hi, a.hi*b.lo, a.hi*b.hi]
        return I(min(v)//SCALE, ceildiv(max(v), SCALE))

    def __truediv__(a, b):
        if b.hi < 0:
            return (-a)/(-b)
        assert b.lo > 0
        v = [(x*SCALE, y) for x in [a.lo, a.hi] for y in [b.lo, b.hi]]
        return I(min(n//d for n, d in v), max(ceildiv(n, d) for n, d in v))

    def square(a):
        lower = 0 if a.lo <= 0 <= a.hi else min(a.lo*a.lo, a.hi*a.hi)
        upper = max(a.lo*a.lo, a.hi*a.hi)
        return I(lower//SCALE, ceildiv(upper, SCALE))

    def sqrt(a):
        assert a.lo >= 0
        lo = math.isqrt(a.lo*SCALE)
        hi = math.isqrt(a.hi*SCALE)
        if hi*hi < a.hi*SCALE:
            hi += 1
        return I(lo, hi)


ZERO = I(0)
ONE = I(SCALE)
TWO = I(2*SCALE)


def cadd(a, b):
    return a[0]+b[0], a[1]+b[1]


def csub(a, b):
    return a[0]-b[0], a[1]-b[1]


def cconj(a):
    return a[0], -a[1]


def cmul(a, b):
    return a[0]*b[0]-a[1]*b[1], a[0]*b[1]+a[1]*b[0]


def crealmul(a, b):
    return a[0]*b, a[1]*b


def cnorm2(a):
    return a[0].square()+a[1].square()



def q(n,d=1):return I.rational(n,d)

def isum(a):
    out=ZERO
    for v in a:out=out+v
    return out

def ident(n):return [[ONE if i==j else ZERO for j in range(n)] for i in range(n)]
def transpose(A):return [list(row) for row in zip(*A)]
def mm(A,B):return [[isum(a*b for a,b in zip(row,col)) for col in zip(*B)] for row in A]
def madd(A,B):return [[a+b for a,b in zip(x,y)] for x,y in zip(A,B)]
def msub(A,B):return [[a-b for a,b in zip(x,y)] for x,y in zip(A,B)]
def scale(A,c):return [[c*a for a in row] for row in A]
def outer(a,b):return [[x*y for y in b] for x in a]
def dot(a,b):return isum(x*y for x,y in zip(a,b))
def mv(A,v):return [dot(row,v) for row in A]
def inner(a,A,b):return dot(a,mv(A,b))
def frob2(A):return isum(x.square() for row in A for x in row)

def inverse(A):
    n=len(A);M=[list(row)+e for row,e in zip(A,ident(n))]
    for j in range(n):
        k=max(range(j,n),key=lambda i:abs(M[i][j].lo+M[i][j].hi))
        M[j],M[k]=M[k],M[j]
        d=M[j][j]
        assert d.lo>0 or d.hi<0
        M[j]=[v/d for v in M[j]]
        for i in range(n):
            if i==j:continue
            z=M[i][j]
            M[i]=[a-z*b for a,b in zip(M[i],M[j])]
    return [row[n:] for row in M]

def real_positive(A):
    n=len(A);L=[[ZERO for _ in range(n)] for _ in range(n)];ds=[]
    for j in range(n):
        d=A[j][j]-isum(L[j][k].square()*ds[k] for k in range(j))
        assert d.lo>0, ('real LDL failure',j,d.lo,d.hi)
        ds.append(d);L[j][j]=ONE
        for i in range(j+1,n):
            L[i][j]=(A[i][j]-isum(L[i][k]*L[j][k]*ds[k] for k in range(j)))/d
    return min(d.lo for d in ds)

def pi_interval():
    def atan_reciprocal(n):
        count=50
        p=sum((Fraction((-1)**j,(2*j+1)*n**(2*j+1)) for j in range(count)),Fraction(0))
        r=Fraction(1,(2*count+1)*n**(2*count+1))
        a=q(p.numerator,p.denominator);b=q((p+r).numerator,(p+r).denominator)
        return I(a.lo,b.hi)
    return q(16)*atan_reciprocal(5)-q(4)*atan_reciprocal(239)


def isolate_w():
    lo=Fraction(1,8);hi=Fraction(13,100)
    def f(x):return 16*x**4+10*x**3-8*x+1
    assert f(lo)>0 and f(hi)<0
    # f'(w)<0 on [0,1/4], since 64w^3+30w^2-8 <= -41/8.
    for _ in range(180):
        mid=(lo+hi)/2
        if f(mid)>0:lo=mid
        else:hi=mid
    a=q(lo.numerator,lo.denominator);b=q(hi.numerator,hi.denominator)
    return I(a.lo,b.hi)


def exact_extremal():
    w=isolate_w()
    rows=[(3112,4752,9708,-9248),(9870,-6480,-28920,-12480),
          (13460,-4590,-34860,-31840),(7780,11880,24270,-23120),
          (-15705,-2430,32280,64320),(7358,-3132,-2478,12368)]
    p=[]
    for row in rows:
        value=ZERO
        for a in reversed(row):value=value*w+q(a)
        p.append(value/q(25875))
    s=[1,1,1,1,-1,1];lam=isum(q(s[i])*p[i] for i in range(6))
    eta=(p[3]-p[0])/p[5];z=(p[0]*p[5]).sqrt()
    qc=[z,ZERO,z*(eta-ONE),z*(ONE-eta),ZERO,-z]
    k=ONE-eta;lam2=lam.square()
    A=p[1]+k*p[3]+eta*p[4]+k.square()*p[5]
    B=p[2]+p[3]+k*p[4]
    C=k.square()*p[0]+eta*p[1]+k*p[2]+p[4]
    E=k*p[1]+p[2]+p[3]
    r1=lam-lam2*(p[0]-k*p[3]+(ONE-k.square())*p[5])
    r2=lam-lam2*((ONE-k.square())*p[0]-k*p[2]+p[5])
    det=A*E-B*C
    t1=(r1*E-B*r2)/det;t2=(A*r2-r1*C)/det
    moment=[lam2,t1,t2,t2-k*lam2+k*t1,eta*t1+k*t2,(ONE-k.square())*lam2+k.square()*t1]
    assert q(834,1000).hi<eta.lo<eta.hi<q(835,1000).lo
    for i in range(6):assert (q(s[i])*p[i]).lo>0
    T=[[moment[abs(i-j)] for j in range(6)] for i in range(6)]
    # A second contact direction proves uniqueness of the norming polynomial.
    c=(-ONE+(q(9)-q(4)*eta).sqrt())/q(4)
    zz=(c,(ONE-c.square()).sqrt())
    def peval(co):
        out=(ZERO,ZERO)
        for a in reversed(co):out=cadd(cmul(out,zz),(a,ZERO))
        return out
    pp=peval(p);dq=peval([q(j)*qc[j] for j in range(1,6)])
    angular=cmul((ZERO,ONE),cmul(zz,dq))
    radial=cmul(cconj(pp),angular)[0]
    assert radial.hi<0 or radial.lo>0
    return p,qc,[q(v) for v in s],lam,T


def verify_local():
    p,qc,s,lam,T=exact_extremal();N=transpose([p,qc]);Nt=transpose(N)
    S0=msub(T,outer(s,s));proj=mm(mm(N,inverse(mm(Nt,N))),Nt)
    G=msub(inverse(madd(S0,proj)),proj)
    real_positive(msub(madd(S0,scale(proj,q(5))),scale(ident(6),q(4))))
    K=[[[q((1 if j-i==h else 0)-(1 if i-j==h else 0)) for j in range(6)] for i in range(6)] for h in range(1,6)]
    E=[[[q(1 if abs(i-j)==h else 0) for j in range(6)] for i in range(6)] for h in range(1,6)]
    cp=[inner(p,A,qc) for A in K];KN=[mm(A,N) for A in K]
    M=[[isum(inner(col1,G,col2) for col1,col2 in zip(transpose(A),transpose(B))) for B in KN] for A in KN]
    bordered=[row+[cp[i]] for i,row in enumerate(M)]+[cp+[ZERO]]
    Binv=inverse(bordered);coef=[];Ki=[]
    vv=[[s[i] if i==j+1 else ZERO for i in range(6)] for j in range(4)]
    for v in vv:
        R1=msub(outer(s,v),outer(v,s));RN=mm(R1,N)
        rhs=[isum(inner(a,G,b) for a,b in zip(transpose(A),transpose(RN))) for A in KN]+[lam*dot(v,qc)]
        co=mv(Binv,rhs)[:5];coef.append(co)
        Ki.append(msub([[isum(co[h]*K[h][i][j] for h in range(5)) for j in range(6)] for i in range(6)],R1))
    Kin=[mm(A,N) for A in Ki]
    H=[[((lam*q(1 if i==j else 0)*s[i+1]*p[i+1])-s[i+1]*p[i+1]*s[j+1]*p[j+1]-s[i+1]*qc[i+1]*s[j+1]*qc[j+1]-isum(inner(a,G,b) for a,b in zip(transpose(Kin[i]),transpose(Kin[j])))) for j in range(4)] for i in range(4)]
    real_positive(msub(H,scale(ident(4),q(3,25))))
    F=[[inner(p,A,p) for A in E],[inner(p,A,qc) for A in E]]
    Fplus=mm(transpose(F),inverse(mm(F,transpose(F))))
    def s2_value(xx):
        v=[isum(vv[j][i]*xx[j] for j in range(4)) for i in range(6)]
        w2=[isum(vv[j][i]*xx[j].square() for j in range(4)) for i in range(6)]
        R2=msub(outer(v,v),scale(madd(outer(s,w2),outer(w2,s)),q(1,2)))
        KK=[[isum(xx[j]*Ki[j][i][k] for j in range(4)) for k in range(6)] for i in range(6)]
        Kn=mm(KK,N);cost=mm(mm(transpose(Kn),G),Kn)
        B=madd(madd(mm(mm(Nt,R2),N),cost),scale(ident(2),inner(xx,H,xx)/q(2)))
        co=mv(Fplus,[B[0][0],B[0][1]])
        return msub([[isum(co[h]*E[h][i][j] for h in range(5)) for j in range(6)] for i in range(6)],R2)
    diagS=[s2_value([ONE if i==j else ZERO for i in range(4)]) for j in range(4)]
    S2=[[None]*4 for _ in range(4)]
    for i in range(4):
        S2[i][i]=diagS[i]
        for j in range(i):
            mixed=s2_value([ONE if k in (i,j) else ZERO for k in range(4)])
            S2[i][j]=S2[j][i]=scale(msub(msub(mixed,diagS[i]),diagS[j]),q(1,2))
    assert isum(frob2(A) for A in Ki).hi < q(100).lo
    assert isum(frob2(A) for row in S2 for A in row).hi < q(289).lo
    aux=[[isum(cp[h]*K[h][i][j] for h in range(5))/dot(cp,cp) for j in range(6)] for i in range(6)]
    import itertools
    raw={};rraw={}
    for i,j,k in itertools.product(range(4),repeat=3):
        R3=scale(msub(outer(vv[i],vv[k]),outer(vv[k],vv[i])),q(-1,2)) if i==j else scale(ident(6),ZERO)
        A=madd(R3,madd(mm(mm(Ki[i],G),S2[j][k]),madd(mm(mm(S2[i][j],G),Ki[k]),mm(mm(mm(mm(Ki[i],G),Ki[j]),G),Ki[k]))))
        raw[i,j,k]=inner(p,A,qc);rraw[i,j,k]=R3
    total=ZERO
    for i,j,k in itertools.product(range(4),repeat=3):
        perms=list(itertools.permutations((i,j,k)))
        g=isum(raw[z] for z in perms)/q(6)
        R3=[[isum(rraw[z][a][b] for z in perms)/q(6) for b in range(6)] for a in range(6)]
        total=total+frob2(msub(scale(aux,g),R3))
    assert total.hi < q(16).lo
    r=Fraction(1,125);kk=10;cc=17;gg=4
    hh=cc*r*r+gg*r**3+4*r**4;ee=kk*r+hh;tail=gg*r**3+4*r**4
    error=4*r**4+(2*kk*r*tail+hh*hh)/4+(kk*r/16)*(2*kk*r*hh+hh*hh)+(kk*r+hh)**2*(hh/16+ee*ee/(16*(4-ee)))
    assert ee<4 and error< Fraction(3,50)*r*r
    assert lam.lo>q(21865297718925,10**13).hi
    assert lam.hi<q(21865297718926,10**13).lo
    print('PASS: exact-parameter local certificate; radius 1/125 in Euclidean phase coordinates')
    print('PASS: range gap >4; H>3/25 I; tensor norms <10,17,4; Schur remainder <3/50 r^2')
    return lam

from fractions import Fraction
# Exact arithmetic in Q[w]/(16w^4+10w^3-8w+1).
class W:
    __slots__=('a',)
    def __init__(self,a=0):
        if isinstance(a,W):self.a=a.a
        elif isinstance(a,(list,tuple)):self.a=tuple(Fraction(v) for v in a)
        else:self.a=(Fraction(a),Fraction(0),Fraction(0),Fraction(0))
        assert len(self.a)==4
    def __add__(a,b):
        b=W(b);return W([x+y for x,y in zip(a.a,b.a)])
    __radd__=__add__
    def __neg__(a):return W([-v for v in a.a])
    def __sub__(a,b):return a+-W(b)
    def __rsub__(a,b):return W(b)+-a
    def __mul__(a,b):
        b=W(b);c=[Fraction(0)]*7
        for i,x in enumerate(a.a):
            for j,y in enumerate(b.a):c[i+j]+=x*y
        for i in range(6,3,-1):
            z=c[i];c[i-1]-=Fraction(5,8)*z;c[i-3]+=z/2;c[i-4]-=z/16
        return W(c[:4])
    __rmul__=__mul__
    def inv(a):
        columns=[(a*W([int(i==j) for i in range(4)])).a for j in range(4)]
        A=[[columns[j][i] for j in range(4)]+[Fraction(int(i==0))] for i in range(4)]
        for j in range(4):
            k=next(i for i in range(j,4) if A[i][j])
            A[j],A[k]=A[k],A[j];d=A[j][j];A[j]=[v/d for v in A[j]]
            for i in range(4):
                if i!=j:
                    z=A[i][j];A[i]=[x-z*y for x,y in zip(A[i],A[j])]
        return W([A[i][4] for i in range(4)])
    def __truediv__(a,b):return a*W(b).inv()
    def __eq__(a,b):return a.a==W(b).a

WGEN=W([0,1,0,0])


def audit_algebra():
    w=WGEN
    rows=[(3112,4752,9708,-9248),(9870,-6480,-28920,-12480),
          (13460,-4590,-34860,-31840),(7780,11880,24270,-23120),
          (-15705,-2430,32280,64320),(7358,-3132,-2478,12368)]
    p=[W(row)/25875 for row in rows];s=[1,1,1,1,-1,1]
    lam=sum((s[i]*p[i] for i in range(6)),W(0))
    assert sum(p,W(0))==1
    assert lam==W([3819,324,-4304,-8576])/1725
    assert 675*lam*lam*lam*lam-1026*lam*lam*lam-936*lam*lam-414*lam+677==0
    eta=(p[3]-p[0])/p[5];k=1-eta;v=[W(1),W(0),-k,k,W(0),W(-1)]
    for h in range(6):
        assert sum((p[i]*p[i+h]+p[0]*p[5]*v[i]*v[i+h] for i in range(6-h)),W(0))==int(h==0), ('autocorrelation',h)
    A=p[1]+k*p[3]+eta*p[4]+k*k*p[5];B=p[2]+p[3]+k*p[4]
    C=k*k*p[0]+eta*p[1]+k*p[2]+p[4];D2=k*p[1]+p[2]+p[3]
    r1=lam-lam*lam*(p[0]-k*p[3]+(1-k*k)*p[5])
    r2=lam-lam*lam*((1-k*k)*p[0]-k*p[2]+p[5])
    det=A*D2-B*C;t1=(r1*D2-B*r2)/det;t2=(A*r2-r1*C)/det;t0=lam*lam
    ts=[t0,t1,t2,t2-k*t0+k*t1,eta*t1+k*t2,(1-k*k)*t0+k*k*t1]
    for i in range(6):
        assert sum((ts[abs(i-j)]*p[j] for j in range(6)),W(0))==lam*s[i],('Tp',i)
        assert sum((ts[abs(i-j)]*v[j] for j in range(6)),W(0))==0,('Tq',i)
    assert sum((v[i]*s[i] for i in range(6)),W(0))==0
    print('PASS: quartic-field identities: complementarity, Tp=Lambda s, Tq=0, and the quartic for Lambda')

from functools import lru_cache
PI = pi_interval()

LOWER_NUM=21865297718925
LOWER_DEN=10**13
MOMENT_DEN=10**12

@lru_cache(None)
def cosine_pi_over(n):
    assert n>=2 and n&(n-1)==0
    if n==2:return ZERO
    return ((ONE+cosine_pi_over(n//2))/q(2)).sqrt()

@lru_cache(None)
def root(n,t):
    t%=n
    if t==0:return ONE,ZERO
    if t==n//4:return ZERO,ONE
    if t==n//2:return -ONE,ZERO
    if t==3*n//4:return ZERO,-ONE
    if t>n//2:return cconj(root(n,n-t))
    if t>n//4:
        a,b=root(n,n//2-t);return -a,b
    c=cosine_pi_over(n//2);step=(c,(ONE-c.square()).sqrt())
    acc=(ONE,ZERO)
    while t:
        if t&1:acc=cmul(acc,step)
        step=cmul(step,step);t//=2
    return acc

sqrt5=q(5).sqrt()
C5=(sqrt5-ONE)/q(4)
S5=((q(10)+q(2)*sqrt5).sqrt())/q(4)
FIFTH=[(ONE,ZERO),(C5,S5)]
FIFTH.extend([cmul(FIFTH[1],FIFTH[1])])
FIFTH.extend([cconj(FIFTH[2]),cconj(FIFTH[1])])

@lru_cache(None)
def mixed_root(n,t,j):return cmul(root(n,t),FIFTH[j%5])

def dft_mass(n,t):
    mass=ZERO
    for j in range(5):
        z=(ONE,ZERO)
        for k in range(1,5):z=cadd(z,mixed_root(n,t[k-1],-j*k))
        mass=mass+cnorm2(z).sqrt()/q(5)
    return mass

def denominator(level):return 32 if level==0 else 32*2**(level+1)
def threshold(level):return q(LOWER_NUM,LOWER_DEN)*cosine_pi_over(32*2**level)


def in_local_ball(level,t):
    n=denominator(level);nd=5*n;half_box=q(2)*PI/q(32*2**level)
    for flag in (0,3):
        for twist in range(5):
            nums=[]
            for j in range(4):
                v=(5*t[j]-n*twist*(j+1)-(nd//2 if j==flag else 0))%nd
                if v>nd//2:v-=nd
                nums.append(v)
            dist=q(sum(v*v for v in nums)).sqrt()*q(2)*PI/q(nd)
            if (dist+half_box).hi<q(1,125).lo:return True
    return False


def children(level,t):
    n=denominator(level+1)
    factor=4 if level==0 else 2
    for bits in itertools.product((-1,1),repeat=4):
        yield tuple((factor*t[j]+bits[j])%n for j in range(4))


def complex_positive_record(level,t,nums):
    n=denominator(level);ph=(0,)+tuple(t)+(0,)
    moments=[(ZERO,ZERO)]+[(q(nums[2*h],MOMENT_DEN),q(nums[2*h+1],MOMENT_DEN)) for h in range(5)]
    diag=threshold(level).square()-ONE
    A=[[(ZERO,ZERO) for _ in range(6)] for _ in range(6)]
    for i in range(6):
        A[i][i]=(diag,ZERO)
        for j in range(i+1,6):
            A[i][j]=csub(moments[j-i],root(n,(ph[j]-ph[i])%n));A[j][i]=cconj(A[i][j])
    L=[[(ZERO,ZERO) for _ in range(6)] for _ in range(6)];ds=[]
    for j in range(6):
        d=diag-isum(cnorm2(L[j][k])*ds[k] for k in range(j))
        assert d.lo>0,('complex LDL fail',level,t,j,d.lo,d.hi)
        ds.append(d);L[j][j]=(ONE,ZERO)
        for i in range(j+1,6):
            e=A[i][j]
            for k in range(j):e=csub(e,crealmul(cmul(L[i][k],cconj(L[j][k])),ds[k]))
            L[i][j]=(e[0]/d,e[1]/d)
    return min(d.lo for d in ds)


def phase_representative(t):
    rev=tuple(reversed(t));neg=tuple((-v)%32 for v in t)
    return min(t,rev,neg,tuple(reversed(neg)))

def initial_representatives():
    for t in itertools.product(range(32),repeat=4):
        if t==phase_representative(t):yield t


