def verify_global(encoded,expected_sha,expected_counts,expected_levels,expected_pivot):
    raw=zlib.decompress(base64.b85decode(encoded))
    assert len(raw)==2136052, ('payload byte count',len(raw))
    assert hashlib.sha256(raw).hexdigest()==expected_sha
    pos=0;counts=[0,0,0,0];levels={};minimum=SCALE*100;maxlevel=0
    def visit(level,t):
        nonlocal pos,minimum,maxlevel
        assert pos<len(raw)
        tag=raw[pos];pos+=1
        assert 0<=tag<=3
        counts[tag]+=1;maxlevel=max(maxlevel,level)
        if tag==0:
            assert dft_mass(denominator(level),t).hi<threshold(level).lo,('DFT bound',level,t)
        elif tag==1:
            assert in_local_ball(level,t),('local inclusion',level,t)
        elif tag==2:
            assert pos+80<=len(raw)
            nums=struct.unpack_from('<10q',raw,pos);pos+=80
            minimum=min(minimum,complex_positive_record(level,t,nums))
        else:
            assert level<=12
            levels[level]=levels.get(level,0)+1
            child_count=0
            for child in children(level,t):visit(level+1,child);child_count+=1
            assert child_count==16
    count=0
    for t in initial_representatives():
        visit(0,t);count+=1
        if count%50000==0:print('verified initial phase orbits',count,'of 262660',flush=True)
    assert count==262660==(32**4+2*32**2+16)//4
    assert pos==len(raw)
    assert counts==expected_counts and levels==expected_levels
    assert maxlevel==7
    assert sum(counts)==count+16*counts[3]
    assert minimum==expected_pivot
    print('PASS: all global phase boxes; initial orbits',count,'nodes',sum(counts),'maximum depth',maxlevel)
    print('DFT/local/Toeplitz/subdivision counts:',counts)
    print('Minimum certified global LDL pivot, in units 10^-50:',minimum)


def main():
    audit_algebra()
    verify_local()
    verify_global(DATA,EXPECTED_SHA,EXPECTED_COUNTS,EXPECTED_LEVELS,EXPECTED_PIVOT)
    print('EXACT CLOSURE: S_5 = S_5(real) = Lambda = 2.186529771892569...')
    print('Lambda is the unique root in (2.18,2.19) of 675X^4-1026X^3-936X^2-414X+677.')
    print('All extremizers: unit scalar and variable rotations of P_star or its coefficient reversal.')

if __name__=='__main__':main()
